#!/usr/bin/env bash
# assemble-packet.sh
#
# Expands exact-excerpt directives in a packet DRAFT into the assembled packet
# BODY, so a verbatim whole design section or table row is copied by a command
# instead of being regenerated by the model (operator ruling, Phillip,
# 2026-10-13: "if there are exerpts which are exactly the same, we should do
# that with a command"; speedup plan P4, fix 4A).
#
# Every non-directive line of the draft passes through byte-for-byte, and
# expanded text is never re-scanned, so directive-looking text inside an
# excerpt stays inert.
set -euo pipefail

show_help() {
  cat <<'HELP'
assemble-packet.sh: expand exact-excerpt directives in a packet draft

Usage: assemble-packet.sh --design <design.md> --in <draft.md> --out <body.md>

Copies <draft.md> to <body.md>, replacing each directive line with exact text.
Only a line that STARTS with exactly one of these three prefixes (including
the trailing space) is a directive:

  @@file <path>
  @@design-section [--quote] <heading path>
  @@design-table-row <heading path> | <first-cell text>

Every other line, diff hunks such as "@@ -1,3 +1,4 @@" included, passes through
byte-for-byte. Expanded text is never re-scanned for directives.

<heading path> is heading text with the leading/trailing "#"s and whitespace
removed (ATX headings only; "#" lines inside code fences are not headings).
"Parent > Child" selects a heading under a parent when the text repeats; the
parent names need not be adjacent ancestors.

@@design-section emits ONE section: the lines after the heading up to the next
heading of ANY level, with the heading line itself omitted and the section's
leading and trailing blank lines dropped. It ends with a "[design: <heading
path>]" line, the path exactly as the directive gave it. --quote prefixes every
emitted line, that last line included, with "> ".

@@design-table-row emits the header row, the separator and every row whose first
cell equals <first-cell text> from the first table in the heading's own section,
then the "[design: <heading path>]" line.

@@file <path> emits the file's bytes. A relative path resolves against the
working directory. The resolved real path (symlinks followed) MUST lie inside
the git toplevel of the working directory and MUST NOT pass through a ".git"
component; anything else, and a working directory outside a git work tree, is
refused with exit 3.

--out is written only when every directive succeeds.

Options:
  --design FILE   Design text that @@design-* directives read (materialize it to
                  one file per run; reuse that file for every call)
  --in FILE       Packet draft
  --out FILE      Assembled packet body (MUST differ from --in)
  -h, --help      Show this help message

Exit codes:
  0  assembled
  1  generic error (unreadable file, missing tool)
  2  usage error (bad flag or argument, empty directive argument)
  3  not found (heading, table, table row, or @@file path; or @@file refused)
  4  ambiguous heading (the message lists the parent paths that disambiguate)
HELP
}

die() {
  echo "assemble-packet.sh: error: $1" >&2
  exit "${2:-1}"
}

DESIGN=""
IN=""
OUT=""

while [[ $# -gt 0 ]]; do
  case "$1" in
  -h | --help)
    show_help
    exit 0
    ;;
  --design | --in | --out)
    [[ $# -ge 2 ]] || die "$1 requires a value" 2
    case "$1" in
    --design) DESIGN="$2" ;;
    --in) IN="$2" ;;
    --out) OUT="$2" ;;
    esac
    shift 2
    ;;
  -*)
    die "unknown option: $1" 2
    ;;
  *)
    die "unexpected argument: $1" 2
    ;;
  esac
done

[[ -n $IN ]] || die "--in is required" 2
[[ -n $OUT ]] || die "--out is required" 2
[[ -r $IN && -f $IN ]] || die "cannot read draft: $IN"
[[ ! $IN -ef $OUT ]] || die "--out must differ from --in (the draft is never overwritten)" 2
if [[ -n $DESIGN ]]; then
  [[ -r $DESIGN && -f $DESIGN ]] || die "cannot read design: $DESIGN"
fi

# The design extractor. Reads the heading path (and, for rows, the first-cell
# text) from the environment so no backslash or quote in them is reinterpreted.
# shellcheck disable=SC2016  # awk program: $0 and friends are awk's, not the shell's
EXTRACT_AWK='
function trim(s) { sub(/^[ \t\r]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
function lstrip3(s,   n) {
  n = 0
  while (n < 3 && substr(s, 1, 1) == " ") { s = substr(s, 2); n++ }
  return s
}
function fail(msg, code) {
  print "assemble-packet.sh: " msg > "/dev/stderr"
  exit code
}
function is_sep(s,   t) {
  t = trim(s)
  if (index(t, "|") == 0) return 0
  return (t ~ /^\|?[ \t]*:?-+:?[ \t]*(\|[ \t]*:?-+:?[ \t]*)*\|?$/)
}
function first_cell(s,   t, out, k, ch) {
  t = trim(s)
  if (substr(t, 1, 1) == "|") t = substr(t, 2)
  out = ""
  for (k = 1; k <= length(t); k++) {
    ch = substr(t, k, 1)
    if (ch == "\\") { out = out ch substr(t, k + 1, 1); k++; continue }
    if (ch == "|") break
    out = out ch
  }
  return trim(out)
}
{ L[NR] = $0 }
END {
  SEP = "\034"
  n = NR
  infence = 0
  nh = 0
  sp = 0
  for (i = 1; i <= n; i++) {
    s = lstrip3(L[i])
    c = substr(s, 1, 1)
    run = 0
    if (c == "`" || c == "~") { while (substr(s, run + 1, 1) == c) run++ }
    if (infence) {
      INF[i] = 1
      if (run >= 3 && c == fc && run >= flen && trim(substr(s, run + 1)) == "") infence = 0
      continue
    }
    if (run >= 3 && !(c == "`" && index(substr(s, run + 1), "`") > 0)) {
      infence = 1; fc = c; flen = run; INF[i] = 1
      continue
    }
    INF[i] = 0
    hl = 0
    while (substr(s, hl + 1, 1) == "#") hl++
    if (hl < 1 || hl > 6) continue
    rest = substr(s, hl + 1)
    if (rest != "" && substr(rest, 1, 1) !~ /[ \t\r]/) continue
    t = trim(rest)
    if (match(t, /[ \t]+#+$/)) t = substr(t, 1, RSTART - 1)
    else if (t ~ /^#+$/) t = ""
    nh++
    HL[nh] = i; HT[nh] = t
    while (sp > 0 && SLV[sp] >= hl) sp--
    anc = ""
    for (k = 1; k <= sp; k++) anc = anc (k > 1 ? SEP : "") HT[SIDX[k]]
    ANC[nh] = anc
    sp++; SLV[sp] = hl; SIDX[sp] = nh
  }

  path = trim(ENVIRON["ASM_HPATH"])
  np = split(path, P, " > ")
  for (k = 1; k <= np; k++) P[k] = trim(P[k])
  ncand = 0
  for (h = 1; h <= nh; h++) {
    if (HT[h] != P[np]) continue
    na = split(ANC[h], A, SEP)
    q = 1
    for (a = 1; a <= na && q < np; a++) if (A[a] == P[q]) q++
    if (q < np) continue
    cand[++ncand] = h
  }
  if (ncand == 0 && np > 1) {
    for (h = 1; h <= nh; h++) if (HT[h] == path) cand[++ncand] = h
  }
  if (ncand == 0) fail("heading not found: " path, 3)
  if (ncand > 1) {
    print "assemble-packet.sh: ambiguous heading: " path " matches " ncand " headings; disambiguate with a parent path:" > "/dev/stderr"
    for (m = 1; m <= ncand; m++) {
      h = cand[m]
      full = ANC[h]
      gsub(SEP, " > ", full)
      full = (full == "" ? "" : full " > ") HT[h]
      print "  line " HL[h] ": " full > "/dev/stderr"
    }
    exit 4
  }

  h = cand[1]
  s0 = HL[h] + 1
  e0 = (h < nh) ? HL[h + 1] - 1 : n
  while (s0 <= e0 && trim(L[s0]) == "") s0++
  while (e0 >= s0 && trim(L[e0]) == "") e0--

  if (ENVIRON["ASM_MODE"] == "section") {
    pfx = (ENVIRON["ASM_QUOTE"] == "1") ? "> " : ""
    for (i = s0; i <= e0; i++) print pfx L[i]
    print pfx "[design: " path "]"
    exit 0
  }

  cell = trim(ENVIRON["ASM_CELL"])
  tbl = 0
  for (i = s0; i < e0; i++) {
    if (!INF[i] && !INF[i + 1] && index(L[i], "|") > 0 && is_sep(L[i + 1])) { tbl = i; break }
  }
  if (!tbl) fail("no table under heading: " path, 3)
  nrow = 0
  for (j = tbl + 2; j <= e0; j++) {
    if (INF[j] || trim(L[j]) == "" || index(L[j], "|") == 0) break
    if (first_cell(L[j]) == cell) rows[++nrow] = L[j]
  }
  if (nrow == 0) fail("table row not found under heading " path ": first cell \"" cell "\"", 3)
  print L[tbl]
  print L[tbl + 1]
  for (r = 1; r <= nrow; r++) print rows[r]
  print "[design: " path "]"
  exit 0
}
'

trim() {
  local s=$1
  s="${s#"${s%%[![:space:]]*}"}"
  s="${s%"${s##*[![:space:]]}"}"
  printf '%s' "$s"
}

TOPLEVEL=""
resolve_toplevel() {
  [[ -n $TOPLEVEL ]] && return 0
  local top
  top=$(git rev-parse --show-toplevel 2>/dev/null) || return 1
  TOPLEVEL=$(realpath -- "$top") || return 1
}

# Prints the resolved real path of $1 to stdout, or returns 3 after a message.
checked_file_path() {
  local path=$1 real rel
  command -v realpath >/dev/null 2>&1 || die "realpath not found"
  [[ -e $path ]] || {
    echo "assemble-packet.sh: @@file path not found: $path" >&2
    return 3
  }
  resolve_toplevel || {
    echo "assemble-packet.sh: @@file refused: working directory is not inside a git work tree" >&2
    return 3
  }
  real=$(realpath -- "$path") || return 1
  case "$real" in
  "$TOPLEVEL"/*) ;;
  *)
    echo "assemble-packet.sh: @@file refused: $path resolves outside the git toplevel ($TOPLEVEL)" >&2
    return 3
    ;;
  esac
  rel=${real#"$TOPLEVEL"/}
  case "/$rel/" in
  */.git/*)
    echo "assemble-packet.sh: @@file refused: $path passes through a .git component" >&2
    return 3
    ;;
  esac
  [[ -f $real && -r $real ]] || {
    echo "assemble-packet.sh: @@file path is not a readable regular file: $path" >&2
    return 3
  }
  printf '%s' "$real"
}

OUT_DIR=$(dirname -- "$OUT")
TMP=$(mktemp "$OUT_DIR/.assemble-packet.XXXXXX") || die "cannot create a temporary file next to $OUT"
cleanup() { rm -f "$TMP"; }
trap cleanup EXIT

need_design() {
  [[ -n $DESIGN ]] || {
    echo "assemble-packet.sh: error: $IN:$lineno: $1 needs --design" >&2
    exit 2
  }
}

fail_directive() {
  echo "assemble-packet.sh: error: $IN:$lineno: directive failed: $line" >&2
  case "$1" in
  3 | 4) exit "$1" ;;
  *) exit 1 ;;
  esac
}

lineno=0
while :; do
  if IFS= read -r line; then
    has_nl=1
  elif [[ -n $line ]]; then
    has_nl=0
  else
    break
  fi
  lineno=$((lineno + 1))
  case "$line" in
  '@@file '*)
    arg=$(trim "${line#'@@file '}")
    [[ -n $arg ]] || {
      echo "assemble-packet.sh: error: $IN:$lineno: @@file needs a path" >&2
      exit 2
    }
    rc=0
    real=$(checked_file_path "$arg" </dev/null) || rc=$?
    [[ $rc -eq 0 ]] || fail_directive "$rc"
    cat -- "$real"
    if [[ -s $real && $(tail -c 1 -- "$real" | wc -l) -eq 0 ]]; then
      printf '\n'
    fi
    ;;
  '@@design-section '*)
    need_design "@@design-section"
    arg=$(trim "${line#'@@design-section '}")
    quote=0
    case "$arg" in
    --quote)
      quote=1
      arg=""
      ;;
    '--quote'[[:space:]]*)
      quote=1
      arg=$(trim "${arg#--quote}")
      ;;
    -*)
      echo "assemble-packet.sh: error: $IN:$lineno: unknown @@design-section flag: ${arg%%[[:space:]]*}" >&2
      exit 2
      ;;
    esac
    [[ -n $arg ]] || {
      echo "assemble-packet.sh: error: $IN:$lineno: @@design-section needs a heading path" >&2
      exit 2
    }
    rc=0
    ASM_MODE=section ASM_QUOTE=$quote ASM_HPATH=$arg LC_ALL=C \
      awk "$EXTRACT_AWK" "$DESIGN" </dev/null || rc=$?
    [[ $rc -eq 0 ]] || fail_directive "$rc"
    ;;
  '@@design-table-row '*)
    need_design "@@design-table-row"
    arg=$(trim "${line#'@@design-table-row '}")
    case "$arg" in
    -*)
      echo "assemble-packet.sh: error: $IN:$lineno: unknown @@design-table-row flag: ${arg%%[[:space:]]*}" >&2
      exit 2
      ;;
    esac
    case "$arg" in
    *' | '*) ;;
    *)
      echo "assemble-packet.sh: error: $IN:$lineno: @@design-table-row needs '<heading path> | <first-cell text>'" >&2
      exit 2
      ;;
    esac
    hpath=$(trim "${arg%%' | '*}")
    cell=$(trim "${arg#*' | '}")
    if [[ -z $hpath || -z $cell ]]; then
      echo "assemble-packet.sh: error: $IN:$lineno: @@design-table-row needs a heading path and a first-cell text" >&2
      exit 2
    fi
    rc=0
    ASM_MODE=row ASM_HPATH=$hpath ASM_CELL=$cell LC_ALL=C \
      awk "$EXTRACT_AWK" "$DESIGN" </dev/null || rc=$?
    [[ $rc -eq 0 ]] || fail_directive "$rc"
    ;;
  *)
    if [[ $has_nl -eq 1 ]]; then
      printf '%s\n' "$line"
    else
      printf '%s' "$line"
    fi
    ;;
  esac
done <"$IN" >"$TMP"

mv -f -- "$TMP" "$OUT"
trap - EXIT
